<div class="row g-4 balance-transfer-calculator-rebuilt"><div class="col-lg-12"><div class="calculator-card"><div class="calculator-body"><div class="row g-3"><div class="col-md-6"><label class="form-label-custom">Current Balance ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="bt-bal" class="form-control form-control-lg" value="8000" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Current APR (%)</label><div class="input-group"><input type="number" id="bt-cur" class="form-control form-control-lg" value="22" min="0"><span class="input-group-text bg-light fw-bold">%</span></div></div><div class="col-md-6"><label class="form-label-custom">New APR (%)</label><div class="input-group"><input type="number" id="bt-new" class="form-control form-control-lg" value="0" min="0"><span class="input-group-text bg-light fw-bold">%</span></div></div><div class="col-md-6"><label class="form-label-custom">Promo Period (Months)</label><div class="input-group"><input type="number" id="bt-promo" class="form-control form-control-lg" value="15" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Transfer Fee (%)</label><div class="input-group"><input type="number" id="bt-fee" class="form-control form-control-lg" value="3" min="0"><span class="input-group-text bg-light fw-bold">%</span></div></div><div class="col-md-6"><label class="form-label-custom">Monthly Payment ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="bt-pmt" class="form-control form-control-lg" value="300" min="0"></div></div></div></div></div></div><div class="col-lg-12"><div class="output-card-themed" style="--tool-hue:220;--tool-color:#3b82f6;--tool-bg:rgba(0,0,0,.02);"><div class="output-hero"><span class="output-hero-label">Balance Transfer Calculator</span><div class="output-hero-value" id="balance-val">—</div><span class="output-hero-unit" id="balance-st">—</span></div><div class="row g-3 mt-3"><div class="col-md-3"><div class="stat-card" style="border-color:#22c55e;background:rgba(0,0,0,.02);"><span class="stat-card-label">INTEREST SAVED</span><span class="stat-card-value" style="color:#22c55e" id="bt-save">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#ef4444;background:rgba(0,0,0,.02);"><span class="stat-card-label">TRANSFER FEE</span><span class="stat-card-value" style="color:#ef4444" id="bt-feea">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#3b82f6;background:rgba(0,0,0,.02);"><span class="stat-card-label">NET SAVINGS</span><span class="stat-card-value" style="color:#3b82f6" id="bt-net">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#a855f7;background:rgba(0,0,0,.02);"><span class="stat-card-label">PAYOFF TIME</span><span class="stat-card-value" style="color:#a855f7" id="bt-payoff">—</span></div></div></div><div class="mt-4" id="balance-ins"></div><div class="row g-2 mt-4"><div class="col-md-4"><button class="btn d-block mx-auto btn-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="balance-cp"><i class="fas fa-copy me-2"></i>Copy Summary</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="balance-rs"><i class="fas fa-rotate-left me-2"></i>Reset</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-primary py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="balance-cb"><i class="fas fa-calculator me-2"></i>Calculate</button></div></div></div></div></div>
<script>document.addEventListener("DOMContentLoaded",function(){const $=id=>document.getElementById(id);function fmt(v){return"$"+Math.round(v).toLocaleString();}function calc(){const bal=parseFloat($("bt-bal").value)||0,cur=(parseFloat($("bt-cur").value)||0)/100/12,nw=(parseFloat($("bt-new").value)||0)/100/12,promo=parseFloat($("bt-promo").value)||1,fee=(parseFloat($("bt-fee").value)||0)/100,pmt=parseFloat($("bt-pmt").value)||1;const feeCost=bal*fee;let b1=bal,i1=0,m1=0;while(b1>0&&m1<600){i1+=b1*cur;b1=b1+b1*cur-pmt;m1++;if(b1<0)b1=0;}let b2=bal+feeCost,i2=0,m2=0;while(b2>0&&m2<600){const r=m2<promo?nw:cur;i2+=b2*r;b2=b2+b2*r-pmt;m2++;if(b2<0)b2=0;}const save=i1-i2;const net=save-feeCost;$("balance-val").textContent=fmt(net);$("bt-save").textContent=fmt(save);$("bt-feea").textContent=fmt(feeCost);$("bt-net").textContent=fmt(net);$("bt-payoff").textContent=m2+" mo";$("balance-st").textContent=net>0?"SAVES MONEY":"NOT WORTH IT";$("balance-st").style.color=net>0?"#22c55e":"#ef4444";let ins=[];ins.push("Interest saved: <strong>"+fmt(save)+"</strong>. Transfer fee: "+fmt(feeCost)+".");ins.push("Net savings: <strong>"+fmt(net)+"</strong>. Payoff in "+m2+" months.");$("balance-ins").innerHTML='<h6 class="fw-bold mb-2"><i class="fas fa-lightbulb me-2 text-warning"></i>Analysis</h6><ul class="list-unstyled mb-0 small">'+ins.map(x=>'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>'+x+'</li>').join("")+'</ul>';}['bt-bal','bt-cur','bt-new','bt-promo','bt-fee','bt-pmt'].forEach(id=>$(id).addEventListener("input",calc));$("balance-cb").addEventListener("click",calc);$("balance-cp").addEventListener("click",function(){navigator.clipboard.writeText("Balance Transfer Calculator: "+$("balance-val").textContent).then(()=>{const o=this.innerHTML;this.innerHTML='<i class="fas fa-check me-2"></i>Copied!';setTimeout(()=>this.innerHTML=o,2e3);});});$("balance-rs").addEventListener("click",()=>{$("bt-bal").value=8000;$("bt-cur").value=22;$("bt-new").value=0;$("bt-promo").value=15;$("bt-fee").value=3;$("bt-pmt").value=300;calc();});calc();});</script>
<style>.balance-transfer-calculator-rebuilt .calculator-card{background:#fff;border:1px solid #e5e7eb;border-radius:20px;padding:2rem;box-shadow:0 4px 24px rgba(0,0,0,.04)}.balance-transfer-calculator-rebuilt .calculator-header{display:flex;align-items:center;gap:1.25rem;margin-bottom:2rem}.balance-transfer-calculator-rebuilt .calculator-header h4{margin:0;font-weight:700;font-size:1.1rem;color:#1e293b}.balance-transfer-calculator-rebuilt .calculator-header p{margin:0;font-size:.85rem;color:#64748b}.balance-transfer-calculator-rebuilt .tool-icon-circle{width:56px;height:56px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.4rem;flex-shrink:0}.balance-transfer-calculator-rebuilt .form-label-custom{font-size:.75rem;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:.8px;margin-bottom:.4rem;display:block}</style>